entries[329466] = { ["name"] = "Spektralstoß", ["text"] = "Nahkampfreichweite\nSofort\nGreift einen Gegner aus dem Geisterreich heraus an, fügt ihm Schattenschaden zu und verringert 9 Sek. lang seine Ausweichchance um 25% sowie seine Rüstung um 25%. Dieser Effekt ist stapelbar." }
entries[329467] = { ["name"] = "Geisterketten", ["text"] = "45 Meter Reichweite\nWirken in 2 sek.\nGeisterketten fliegen auf einen Spielercharakter zu, fügen ihm 10 Schattenschaden zu und verringern seine Bewegungsgeschwindigkeit für 9 Sek. um 50%." }
entries[329468] = { ["name"] = "Verschlingen", ["text"] = "300 Meter Reichweite\nSofort\nDer hungernde Zerstörer hüllt alle Spielercharaktere in verschlingende Energien, die die nächsten 25 Schaden absorbieren.\n\nSobald das Wirken abgeschlossen ist, zehrt der hungernde Zerstörer sämtliche verbleibenden Absorptionen auf, gewährt sich selbst einen Schild in Höhe von 500% des aufgezehrten Werts und fügt allen Spielercharakteren 30 Schattenschaden zu.\n\nSolange er in den Schild gehüllt ist, erhält der hungernde Zerstörer alle 1 Sek. zusätzlich 2 Energie." }
entries[329469] = { ["name"] = "Zellentür" }
entries[329470] = { ["name"] = "Schwelendes Gefieder", ["text"] = "Sofort\nBrennendes Gefieder stößt Feuer aus und fügt allen Gegnern innerhalb von 6 Metern alle 2.5 Sek. 7407 Feuerschaden zu." }
